#!/bin/bash
# up_std_1111 — 11-11 §7: 표준(Smac · 0.01 Hz) 배포(Jetson, 로버 안 움직임 · 빌드 안 함 · 노드 안 띄움).
#   하는 일: ① navigation.launch.py → ~/ros2_ws/src/rover_navigation/launch/(설치본은 src 링크라 바로 반영, 백업 /tmp/deploy_backup_1111) ② prep_patrol.sh → /tmp
#            ③ md5 대조(PC 저장소 판 nav 8b6463867f50 · prep 89889adfb917) ④ 설치본 링크 확인 ⑤ ros2 launch --show-args 로 planner · replan_hz 기본값 확인.
#   파일 내용은 아래 base64(PC 저장소 판, CR 제거)로 들어 있다. 인자: 없음. 출력: 표준 출력.
set -e; S=~/ros2_ws/src/rover_navigation/launch/navigation.launch.py; B=/tmp/deploy_backup_1111; mkdir -p $B; cp $S $B/; cp /tmp/prep_patrol.sh $B/ 2>/dev/null || true
echo '' | base64 -d > $S
echo '' | base64 -d > /tmp/prep_patrol.sh
echo "== md5: nav $(md5sum < $S | cut -c1-12)(PC 8b6463867f50) · prep $(md5sum < /tmp/prep_patrol.sh | cut -c1-12)(PC 89889adfb917)"
I=~/ros2_ws/install/rover_navigation/share/rover_navigation/launch/navigation.launch.py; [ -L $I ] && echo "== 설치본 링크 -> $(readlink -f $I)" || echo "== ⚠ 설치본이 링크 아님"
set +e; source /opt/ros/humble/setup.bash; source ~/ros2_ws/install/setup.bash
ros2 launch rover_navigation navigation.launch.py --show-args 2>&1 | awk '/^ +'"'"'/{n=$0} /default:/{ if (n ~ /replan_hz|.planner.|mppi_viz|global_camera/) {gsub(/^ +/,"",n); gsub(/^ +/,"",$0); print "  " n, $0} }'
echo "== prep_patrol 기본 줄"; grep -a 'EXTRA_NAV=' /tmp/prep_patrol.sh | cut -c1-200
